<template><ElSpace direction="vertical" fill class="v1-page" :size="20"><ElSpace class="v1-spread"><ElText size="large" tag="strong">监控画面</ElText><ElButton type="primary" :disabled="!admin" @click="edit()">新增画面</ElButton></ElSpace><ElEmpty v-if="!cameras.length" description="暂无画面" /><ElRow :gutter="20"><ElCol v-for="c in cameras" :key="c.id" :span="12" class="v1-card-col"><ElCard shadow="never"><template #header><ElSpace class="v1-spread"><ElSpace><strong>{{c.name}}</strong><ElTag>{{c.area}}</ElTag><ElTag v-if="c.kind==='illustration'" type="warning">未接入</ElTag></ElSpace><ElButton text :disabled="!admin" @click="edit(c)">编辑</ElButton></ElSpace></template><ElEmpty v-if="c.kind==='illustration'" description="暂无摄像头" /><ElImage v-else-if="['snapshot','mjpeg'].includes(c.kind)" :src="imageUrl(c)" :alt="c.name" fit="contain" style="width:100%;height:300px"><template #error><ElEmpty description="画面无法加载" /></template></ElImage><video v-else :src="c.url" controls muted playsinline style="width:100%;height:300px" /></ElCard></ElCol></ElRow></ElSpace><ElDrawer v-model="open" title="监控画面" direction="rtl" size="min(500px,100vw)"><ArtForm v-model="draft" :items="fields" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElAlert v-if="error" :title="error" type="error" :closable="false" /><template #footer><ElButton @click="open=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="save">保存</ElButton></template></ElDrawer></template>
<script setup>import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';import {api} from './api';const props=defineProps({spaceId:String,cameras:Array,user:Object});const emit=defineEmits(['refresh']);const snapshotURLs=ref({}),latestRequests=new Map();let frameTimer=0,requestNumber=0;function cacheURL(url){try{const u=new URL(url,location.origin);u.searchParams.set('_t',Date.now());return u.href}catch{return ''}}function refreshSnapshots(){if(document.hidden)return;for(const c of props.cameras.filter(c=>c.kind==='snapshot')){const number=++requestNumber,url=cacheURL(c.url);latestRequests.set(c.id,number);const image=new Image();image.onload=()=>{if(latestRequests.get(c.id)===number)snapshotURLs.value={...snapshotURLs.value,[c.id]:url}};image.src=url}}function imageUrl(c){return c.kind==='snapshot'?(snapshotURLs.value[c.id]||cacheURL(c.url)):c.url}function visibility(){if(!document.hidden)refreshSnapshots()}onMounted(()=>{refreshSnapshots();frameTimer=window.setInterval(refreshSnapshots,1000);document.addEventListener('visibilitychange',visibility)});onBeforeUnmount(()=>{clearInterval(frameTimer);document.removeEventListener('visibilitychange',visibility);latestRequests.clear()});watch(()=>props.cameras,refreshSnapshots,{deep:true});const admin=computed(()=>['admin','demo'].includes(props.user.role)),open=ref(false),busy=ref(false),draft=ref({}),error=ref('');const fields=computed(()=>[{key:'name',label:'名称',type:'input'},{key:'area',label:'区域',type:'input'},{key:'kind',label:'类型',type:'select',props:{options:[{value:'illustration',label:'未接入'},{value:'snapshot',label:'JPEG 实时快照'},{value:'mjpeg',label:'MJPEG 图片流'},{value:'video',label:'视频'}]}},...(draft.value.kind!=='illustration'?[{key:'url',label:'HTTP / HTTPS 地址',type:'input'}]:[])]);function edit(c){draft.value=c?{...c}:{name:'',area:'',kind:'illustration',url:''};error.value='';open.value=true}async function save(){busy.value=true;try{await api('cameras',{...draft.value,space_id:props.spaceId});open.value=false;emit('refresh')}catch(e){error.value=e.message}finally{busy.value=false}}</script>
